CREATE TABLE public.partnership_packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, title_en text, description text NOT NULL DEFAULT '', description_en text, fee integer NOT NULL DEFAULT 0 CHECK(fee >= 0), published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.partnership_packages TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.partnership_packages TO authenticated;
GRANT ALL ON public.partnership_packages TO service_role;
ALTER TABLE public.partnership_packages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public published partnership packages" ON public.partnership_packages FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY "Staff manages partnership packages" ON public.partnership_packages FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE TABLE public.partnership_payment_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), bank_name text NOT NULL DEFAULT '', account_number text NOT NULL DEFAULT '', account_holder text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', instructions_en text, enabled boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(NOT enabled OR (length(trim(bank_name))>0 AND length(trim(account_number))>0 AND length(trim(account_holder))>0)));
GRANT SELECT ON public.partnership_payment_settings TO anon;
GRANT SELECT,INSERT,UPDATE ON public.partnership_payment_settings TO authenticated;
GRANT ALL ON public.partnership_payment_settings TO service_role;
ALTER TABLE public.partnership_payment_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public enabled bank details" ON public.partnership_payment_settings FOR SELECT TO anon,authenticated USING(enabled);
CREATE POLICY "Staff manages partnership payment settings" ON public.partnership_payment_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE TABLE public.partnership_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE, package_id uuid NOT NULL REFERENCES public.partnership_packages(id), package_title text NOT NULL, amount integer NOT NULL CHECK(amount>0), full_name text NOT NULL, organization text NOT NULL, email text NOT NULL, phone text NOT NULL DEFAULT '', message text NOT NULL DEFAULT '', bank_name text NOT NULL, account_number text NOT NULL, account_holder text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','cancelled')), confirmed_at timestamptz, confirmed_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.partnership_orders TO authenticated;
GRANT ALL ON public.partnership_orders TO service_role;
ALTER TABLE public.partnership_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff reads partnership orders" ON public.partnership_orders FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE POLICY "Staff updates partnership orders" ON public.partnership_orders FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE FUNCTION public.guard_partnership_order_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (to_jsonb(NEW)-ARRAY['status','confirmed_at','confirmed_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','confirmed_at','confirmed_by']) THEN RAISE EXCEPTION 'Order details are immutable'; END IF; IF NEW.status='paid' AND OLD.status<>'paid' THEN NEW.confirmed_at=now(); NEW.confirmed_by=auth.uid(); ELSIF NEW.status<>'paid' THEN NEW.confirmed_at=NULL; NEW.confirmed_by=NULL; ELSE NEW.confirmed_at=OLD.confirmed_at; NEW.confirmed_by=OLD.confirmed_by; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_partnership_order_update BEFORE UPDATE ON public.partnership_orders FOR EACH ROW EXECUTE FUNCTION public.guard_partnership_order_update();